entradas.ejemplo:
// el de siempre: pantalla completa, grande
game.osd.define('intro', {
  html: '<div class="mc-osd-panel">'
      +   '<div class="mc-osd-title">VoxelForge v1.0</div>'
      +   '<button class="mc-osd-btn">JUGAR</button>'
      +   '<button class="mc-osd-btn">CONSTRUIR</button>'
      + '</div>'
});

// el mismo, compacto y en una esquina
game.osd.define('ajustes', {
  sitio:'abajo-derecha',
  escala:0.6, boton:18,          // caja pequeña, letra igual de nítida
  ancho:0,                       // ← lo que más encoge: el botón mide lo que su texto
  hueco:6, relleno:[12,16], rellenoBoton:[6,12],
  html: '<div class="mc-osd-panel fila">'
      +   '<button class="mc-osd-btn">VOLAR</button>'
      +   '<button class="mc-osd-btn">SALIR</button>'
      + '</div>'
});

game.osd.abrir('ajustes');

const htmlVolar = () =>
  '<div class="mc-osd-panel">'
  + '<button class="mc-osd-btn" data-osd="VOLAR">VOLAR: ' + (game.volar.valueOf() ? 'ON' : 'OFF') + '</button>'
  + '</div>';

game.osd.alPulsar('VOLAR', () => { game.volar(); game.osd.html(htmlVolar()); });

// vuela hasta la vista que quieras (F) y luego, en F12:
game.osd.encuadre();
// → game.osd.define('menu', {mapa:'voxelforge', pos:[55.66, 3.96, 63.37], yaw:0, pitch:-26});

game.bloques.define('hab:escalera', { trepable:true, subida:4, bajada:5 });
game.bloques.define('hab:placa',    { alPisar(c){ /* c.quien = 'jugador' | 'agente' */ } });
game.bloques.define('hab:hielo',    { velocidad:2, deslizamiento:1.2 });

game.bloques.info();   // ← el descubridor: la clave EXACTA de lo que piso / tengo delante

// altura del terreno en (x, z): la primera celda no vacía bajando desde arriba
function cima(x, z){
  if(!mcInside(x, 0, z)) return -1;
  for(let y = mc.dim.y - 1; y >= 0; y--) if(mc.grid[mcIdx(x, y, z)]) return y;
  return -1;
}

mc.pos = [x + 0.5, cima(x, z) + 1, z + 0.5];
mc.vel = [0, 0, 0];
mcUnstick();

mc.pos = [x + 0.5, cima(x, z) + 1, z + 0.5];   // en el centro de la celda, de pie
mc.vel = [0, 0, 0];
mc.onGround = false;

// 1 · desmontar la anterior ANTES de montar la nueva
if (mc._intro && mc._intro.parar) mc._intro.parar();

const intro = mc._intro = {
  raf: 0, viva: true,
  parar(){ if(!this.viva) return; this.viva = false; cancelAnimationFrame(this.raf);
           if (mc._intro === this) mc._intro = null; }
};

game.cieloColor('#ff8844');   // atardecer: el agua lo refleja al instante
game.cieloColor([0.1,0.1,0.2]); // noche
game.cieloColor('reset');

game.agentes.guardar({
  nombre: 'Luciérnaga',
  raiz: { pieza:'asset:assets/cubo-blanco-brillante.vox.json', rot:0 },
  piezas: [],
  seguir: { objetivo:'jugador', ejes:'xyz', distancia:3, deteccion:0, velocidad:6 },
  escala: 0.1
});

// por id de uno ya guardado
game.esqueletos.crear('luciernaga', mc.pos[0] + 3, mc.pos[1], mc.pos[2])
  .then(rig => console.log('plantada', rig && rig.id));

// con el documento entero, sin guardarlo antes
game.esqueletos.crear({
  nombre: 'Guardián', raiz:{ pieza:'asset:assets/guardian.vox.json' }, piezas:[]
}, 40, 20, 40);
